import json
import sys
import requests
import subprocess

def main():
    if len(sys.argv) != 2:
        print("Usage: python service_watch.py <config_file>", file=sys.stderr)
        sys.exit(1)

    config_file = sys.argv[1]
    try:
        with open(config_file) as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error reading config file: {e}", file=sys.stderr)
        sys.exit(1)

    if "targets" not in config or not isinstance(config["targets"], list):
        print("Invalid config format: missing or invalid 'targets' array", file=sys.stderr)
        sys.exit(1)

    all_passed = True

    for target in config["targets"]:
        if not isinstance(target, dict) or "name" not in target or "url" not in target or "command" not in target:
            print(f"Invalid target format in config: missing required fields", file=sys.stderr)
            sys.exit(1)

        name = target["name"]
        url = target["url"]
        command = target["command"]

        try:
            response = requests.get(url, timeout=5)
            if response.status_code == 200:
                print(f"OK {name}")
            else:
                print(f"FAIL {name} {response.status_code}")
                all_passed = False
                subprocess.run(command, shell=True, check=True)
        except requests.exceptions.RequestException:
            print(f"ERROR {name}")
            all_passed = False

    sys.exit(0 if all_passed else 1)

if __name__ == "__main__":
    main()

import sys
import requests
import subprocess

def main():
    if len(sys.argv) != 3:
        print("Usage: python service_watch.py <url> <command>", file=sys.stderr)
        sys.exit(1)

    url = sys.argv[1]
    command = sys.argv[2]

    try:
        response = requests.get(url, timeout=5)
        if response.status_code == 200:
            print("OK")
            sys.exit(0)
        else:
            print(f"FAIL {response.status_code}")
            subprocess.run(command, shell=True, check=True)
            sys.exit(1)
    except (requests.exceptions.RequestException, requests.exceptions.Timeout):
        print("ERROR")
        sys.exit(1)

if __name__ == "__main__":
    main()

